            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "The art of war is of vital importance to the State. It is a matter of life and death, a road either to safety or to ruin. Hence it is a subject of inquiry which can on no account be neglected.", Author = "Sun Tzu" },
