            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "It is the rule in war, if ten times the enemy's strength, surround them; if five times, attack them; if double, be able to divide them; if equal, engage them; if fewer, defend against them; if weaker, be able to avoid them.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "For to win one hundred victories in one hundred battles is not the acme of skill. To subdue the enemy without fighting is the acme of skill.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "The best victory is when the opponent surrenders of its own accord before there are any actual hostilities... It is best to win without fighting.", Author = "Sun Tzu" },
