            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "Management of many is the same as management of few. It is a matter of organization.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "A skilled commander seeks victory from the situation and does not demand it of his subordinates.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "Be extremely subtle, even to the point of formlessness. Be extremely mysterious, even to the point of soundlessness. Thereby you can be the director of the opponent's fate.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "All men can see these tactics whereby I conquer, but what none can see is the strategy out of which victory is evolved.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "The ultimate in disposing one's troops is to be without ascertainable shape. Then the most penetrating spies cannot pry in nor can the wise lay plans against you.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "And therefore those skilled in war bring the enemy to the field of battle and are not brought there by him.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "When the enemy is at ease, be able to weary him; when well fed, to starve him; when at rest, to make him move. Appear at places to which he must hasten; move swiftly where he does not expect you.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "Let your rapidity be that of the wind, your gentleness that of the forest. In raiding and plundering be like fire, be immovable like a mountain. Be as hard to know as the shadow and move as fast as lightning.", Author = "Sun Tzu" },
