            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "The art of war teaches us to rely not on the likelihood of the enemy's not coming, but on our own readiness to receive him; not on the chance of his not attacking, but rather on the fact that we have made our position unassailable.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "Too frequent rewards indicate that the general is at the end of his resources; too frequent punishments that he is in acute distress.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "A leader leads by example not by force.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "If words of command are clear and distinct, if orders are thoroughly understood, the general is to blame. But if his orders are clear, and the soldiers nevertheless disobey, then it is the fault of their officers.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "The general who advances without coveting fame and retreats without fearing disgrace, whose only thought is to protect his country and do good service for his sovereign, is the jewel of the kingdom.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "Treat your men as you would your own beloved sons. And they will follow you into the deepest valley.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "Speed is the essence of war. Take advantage of the enemy's unpreparedness; travel by unexpected routes and strike him where he has taken no precautions.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "Bestow rewards without respect to customary practice; publish orders without respect to precedent. Thus you may employ the entire army as you would one man.", Author = "Sun Tzu" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sun_Tzu", Text = "Now the reason the enlightened prince and the wise general conquer the enemy whenever they move and their achievements surpass those of ordinary men is foreknowledge.", Author = "Sun Tzu" },
